html=r"""<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>云途万里 · 机场美术图册</title><style>@font-face{font-family:Noto;src:url('../../../assets/fonts/NotoSansSC-Variable.ttf')}*{box-sizing:border-box}body{margin:0;background:#123e35;color:#f5e9cc;font:15px Noto,sans-serif}header,main{max-width:1500px;margin:auto;padding:26px}h1{font-weight:600;font-size:28px;margin:0 0 10px}.meta{color:#c2d1b3;line-height:1.8}nav{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}button,input{font:inherit;border:1px solid #cba85f;border-radius:12px;padding:11px 18px;background:#f1ead7;color:#19483a}button{cursor:pointer}button[aria-pressed=true]{background:#45806b;color:white}input{min-width:250px;margin-left:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:20px}article{border:1px solid #8a9e78;border-radius:16px;overflow:hidden;background:#e8e1cc;color:#194438;padding:14px;min-width:0}.image{height:270px;display:flex;align-items:center;justify-content:center;background:repeating-conic-gradient(#ddd6c3 0% 25%,#e8e1cc 0% 50%) 50%/24px 24px;border-radius:10px;overflow:hidden}.image img{object-fit:contain;max-width:100%;max-height:100%}.id{font-size:13px;overflow-wrap:anywhere;color:#426450;margin-top:10px}h2{font-size:17px;margin:12px 0 4px}.notes{font-size:13px;line-height:1.8;color:#c4d0ba;margin:14px 0}a{color:inherit}#count{margin:14px 0}.animationControls{display:flex;gap:10px;align-items:center;margin-bottom:20px}footer{padding:40px 0;font-size:13px;color:#bcccb0}.empty{padding:50px;font-size:22px}</style><header><a data-brand-navigation="true" href="../../../index.html" style="display:inline-flex;align-items:center;gap:10px;color:inherit;text-decoration:none;margin:0 0 12px"><img src="../../../branding/yuntu-wanli/logo-symbol-64.png" alt="云途万里" width="48" height="48" style="object-fit:contain"><span>云途万里 · 美术交付首页</span></a><h1>云途万里 · 机场美术图册</h1><div class="meta">10种机场（9种可建＋油井共用平台） · 74个地块ID · 265个原始布局坐标<br>139张正式模块与状态PNG，含20张雷达／风旗派生帧；2张打包帧表另计。点击画面可查看完整尺寸。</div><nav><button data-tab="layouts" aria-pressed="true">完整机场</button><button data-tab="tiles" aria-pressed="false">74个地块</button><button data-tab="animations" aria-pressed="false">动画循环</button><input id="search" placeholder="搜索机场、地块编号或名称" aria-label="搜索"></nav><div class="notes">此页是美术拼装与状态预览。机场保留源坐标和完整占地；共享终端楼等模块是道家风格改绘。滑行路径对齐、飞机排序与Unity运行验证留待接入阶段。<br>雷达是绘画部件的投影扫动，风旗是布料像素变形；20帧均为明确标注的确定性派生。</div></header><main><div class="animationControls" hidden><button id="pause">暂停动画</button><span>固定支撑与接地点 · 雷达12帧 · 风旗8帧</span></div><div id="count"></div><section class="grid" id="grid"></section><footer><a href="../../../assets/world/infrastructure/airports/manifest.json">资源与源布局清单</a> · <a href="../../../records/world-production/airport-validation.json">本地检查记录</a> · <a href="../../../docs/AIRPORT_ART_DELIVERY.md">规格与Unity建议</a><br>F盘只读；未Git提交；用户画面验收待确认；未在Unity验证。</footer></main><script>const DATA=__DATA__;let tab='layouts',paused=false;const grid=document.querySelector('#grid'),search=document.querySelector('#search');const url=p=>'../../../'+p;function render(){grid.innerHTML='';let items=DATA[tab].filter(a=>JSON.stringify(a).toLowerCase().includes(search.value.toLowerCase()));document.querySelector('#count').textContent=items.length+' / '+DATA[tab].length+' 项';document.querySelector('.animationControls').hidden=tab!=='animations';for(const a of items){let card=document.createElement('article'),link=document.createElement('a'),box=document.createElement('div'),img=new Image();box.className='image';img.alt=a.name||a.id;img.loading='lazy';img.src=url(a.image||a.frames[0]);link.href=img.src;link.target='_blank';box.append(img);link.append(box);card.append(link);let title=document.createElement('h2');title.textContent=a.name||a.id;card.append(title);let sub=document.createElement('div');sub.className='id';sub.textContent=a.id+(tab==='layouts'?' · '+a.footprint.join('×')+' 地块 · '+a.count+' 源坐标':tab==='animations'?' · '+a.frames.length+' 帧 · '+a.method:' · 原始ID '+a.index);card.append(sub);if(tab==='animations'){img.dataset.animation=a.id;img.loading='eager'}grid.append(card)}if(!items.length)grid.innerHTML='<div class="empty">没有匹配结果</div>'}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;search.value='';document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});search.oninput=render;document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'播放动画':'暂停动画'};let timer=0;function tick(t){if(!paused&&t-timer>90){timer=t;document.querySelectorAll('[data-animation]').forEach(img=>{let a=DATA.animations.find(x=>x.id===img.dataset.animation),k=Math.floor(t/a.durationsMs[0])%a.frames.length;img.src=url(a.frames[k])})}requestAnimationFrame(tick)}render();requestAnimationFrame(tick);window.airportGallery={DATA,getTab:()=>tab};</script></html>"""
